class Broken(BaseException): pass
original=Broken('original')
class Sink(io.BytesIO):
    def __init__(self, bad_close=False): super().__init__(); self.closes=0; self.bad_close=bad_close
    def close(self):
        self.closes+=1
        super().close()
        if self.bad_close: raise Broken('cleanup')

def two_files():
    raw=body(b'first')
    return raw[:raw.index(b'--'+B+b'--')]+body(b'second')

for failure in ('read','factory','write','seek','collection','decoder'):
    sinks=[]
    def factory(**kw):
        if failure=='factory' and sinks: raise original
        sink=Sink(True); sinks.append(sink)
        if len(sinks)==2 and failure=='write': sink.write=lambda b: (_ for _ in ()).throw(original)
        if len(sinks)==2 and failure=='seek': sink.seek=lambda n: (_ for _ in ()).throw(original)
        return sink
    class Read(io.BytesIO):
        def read(self,n):
            if failure=='read' and len(sinks)==2: raise original
            return super().read(1)
    class Collection(MultiDict):
        def __init__(self,*args):
            if failure=='collection': raise original
            super().__init__(*args)
    raw=two_files()
    if failure=='decoder': raw=raw[:-30]
    stream=Read(raw)
    try: MultiPartParser(stream_factory=factory,cls=Collection).parse(stream,B,None)
    except BaseException as e:
        if failure=='decoder': assert isinstance(e,ValueError)
        else: assert e is original,(failure,e)
    else: raise AssertionError(failure)
    assert sinks and all(s.closes==1 for s in sinks),failure
    assert not stream.closed

